window.GuanwuHeritage=(()=>{
 let province='全部',category='all',query='',map=null,frame=0;
 const sites=()=>GUANWU_WORLD_HERITAGE.sites;
 const byId=id=>sites().find(s=>s.id===id);
 const provinces=()=>[...new Set(sites().flatMap(s=>s.provinces))];
 const type=s=>s.category==='mixed'?'文化与自然双遗产':'世界文化遗产';
 const matches=()=>sites().filter(s=>(province==='全部'||s.provinces.includes(province))&&(category==='all'||s.category===category)&&(!query||[s.name,s.englishName,s.theme,...s.provinces,...(s.cities||[])].join(' ').toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>b.year-a.year||a.name.localeCompare(b.name,'zh-CN'));
 function card(s){return `<article class="heritage-card"><a href="#heritage/${s.id}" class="heritage-card-image">${photo(s.cover,'loading="lazy"')}<span>${s.year} · UNESCO</span><b>${s.category==='mixed'?'双遗产':'文化遗产'}</b></a>${saveButton('heritage:'+s.id)}<div><small>${s.provinces.map(esc).join(' · ')}</small><h2><a href="#heritage/${s.id}">${esc(s.name)}</a></h2><p>${esc(s.theme)}</p><a class="text-link" href="#heritage/${s.id}">读懂这一处遗产 ↗</a></div></article>`}
 function results(){const found=matches();return `<div class="heritage-result-count" role="status">${province==='全部'?'中国世界文化遗产目录':esc(province)+' · 名录项目'} <strong>${found.length}</strong> 项</div>${found.length?`<div class="heritage-grid">${found.map(card).join('')}</div>`:'<div class="soft-empty">这个条件下暂时没有找到项目，换个省份或关键词试试。</div>'}`}
 function page(){return `<section class="heritage-intro"><div><div class="eyebrow">A WORLD OF HERITAGE · CHINA</div><h1>从一处遗产，<br>走进一方天地。</h1><p>沿着中国的山河与文明，找到下一次出发的理由。</p><div class="heritage-stats"><span><b>42</b> 文化遗产</span><span><b>4</b> 文化与自然双遗产</span><span><b>${provinces().length}</b> 省级地区标签</span></div></div><a class="heritage-feature" href="#heritage/wh-1765">${photo(byId('wh-1765')?.cover,'fetchpriority="high"')}<span>2026 · 新列入名录</span><div><small>JINGDEZHEN</small><h2>一窑火，<br>如何连接世界？</h2><p>景德镇手工瓷业遗存 ↗</p></div></a></section><div class="heritage-guide-note"><strong>46 项，按正式名录收录。</strong><p>覆盖中国全部已列入的文化与双遗产项目。长城、大运河等跨省遗产按整体计一项；省份标签用于寻找已核实的相关组成地，不表示每段或全省范围都属于遗产。<a href="${GUANWU_WORLD_HERITAGE.source}" target="_blank" rel="noopener">查看 UNESCO 名录 ↗</a></p></div><div class="heritage-filters"><label><span>想去哪个省份</span><select id="heritage-province"><option value="全部">全部省级地区</option>${provinces().map(p=>`<option value="${esc(p)}" ${province===p?'selected':''}>${esc(p)}</option>`).join('')}</select></label><label class="heritage-search-label"><span>带着好奇找一找</span><input id="heritage-search" type="search" value="${esc(query)}" placeholder="莫高窟、福建、园林…" aria-label="搜索世界遗产"></label><label><span>遗产类型</span><select id="heritage-category"><option value="all" ${category==='all'?'selected':''}>全部类型</option><option value="cultural" ${category==='cultural'?'selected':''}>文化遗产</option><option value="mixed" ${category==='mixed'?'selected':''}>文化与自然双遗产</option></select></label></div><div id="heritage-results">${results()}</div><p class="tiny-note">核对日期：${esc(GUANWU_WORLD_HERITAGE.updated)}。本目录不含纯自然遗产、预备名单和非物质文化遗产；名录条目完整收录，串联项目的组成点位不是逐处独立导览。</p>`}
 function detail(id){const s=byId(id);if(!s)return missing();const credit=images[s.cover];return `<div class="detail-breadcrumb"><a href="#heritage">世界遗产</a><span>/</span>${s.provinces.map(esc).join(' · ')}</div><div class="heritage-detail-heading"><div class="eyebrow">${s.year} · ${type(s)} · UNESCO ${s.unescoId}</div><h1>${esc(s.name)}</h1><p>${esc(s.englishName)}</p><div>${saveButton('heritage:'+s.id,'outline-btn')}<button class="solid-btn" data-heritage-listen="${s.id}">▷ 听一段遗产简介</button><button class="text-link" data-voice-settings>换一种讲述声音 ↗</button></div></div><button class="heritage-detail-photo" data-gallery="heritage:${s.id}:0" aria-label="放大${esc(s.name)}资料图片">${photo(s.cover,'fetchpriority="high"')}<span>放大细看 ↗</span></button><p class="photo-note">${esc(credit?.caption)} · <button class="text-link" data-action="credits">摄影与许可 ↗</button></p><div class="heritage-reading-grid"><section><div class="eyebrow">WHY IT MATTERS</div><h2>${esc(s.theme)}</h2><p class="heritage-lead">${esc(s.intro)}</p><div class="heritage-scope"><strong>先认清范围，再出发。</strong><p>${esc(s.componentsNote||'以 UNESCO 公布的遗产边界为准。')}</p>${s.provinceScope?`<p>${esc(s.provinceScope)}</p>`:''}</div></section><aside><small>YOUR FIRST VISIT</small><h3>带上自己的问题。</h3><ul>${s.tips.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><button class="outline-btn" data-heritage-ask="${id}">请伴游帮我读懂这处遗产 ↗</button></aside></div><section class="section"><div class="section-head"><div class="section-title"><h2>先看这三个细节</h2><span>A CLOSER LOOK</span></div></div><div class="highlight-grid">${s.highlights.map((h,i)=>`<article><small>0${i+1}</small><h3>${esc(h.title)}</h3><p>${esc(h.text)}</p><a href="${esc(h.source.url)}" target="_blank" rel="noopener">${esc(h.source.title)} ↗</a></article>`).join('')}</div></section><section class="section heritage-chapters"><div class="section-head"><div class="section-title"><h2>留一点时间，继续读</h2><span>READING NOTES</span></div></div><p class="tiny-note">简介提供三套 AI 合成语音；下列完整章节为文字阅读。</p>${s.chapters.map((c,i)=>`<details ${i===0?'open':''}><summary><span>0${i+1}</span>${esc(c.title)}<b>＋</b></summary><p>${esc(c.text)}</p></details>`).join('')}</section><div class="heritage-location-grid"><section><div class="eyebrow">A REFERENCE, NOT AN ENTRANCE</div><h2>在地图上，找到它。</h2><p class="tiny-note">这是 UNESCO 公布的遗产参考点，可能代表整个串联项目。请从具体组成地的官方信息核对游客入口、开放及交通。</p><div id="heritage-map" class="heritage-map" aria-label="遗产参考位置"></div><a class="text-link" href="https://uri.amap.com/search?keyword=${encodeURIComponent(s.name)}&callnative=0" target="_blank" rel="noopener">按遗产名称查找参观地点 ↗</a></section><section><h2>资料与出发准备</h2>${sourceLinks(s.sources)}${s.relatedMuseums?.length?`<h3>继续走进博物馆</h3>${s.relatedMuseums.map(id=>{const m=museums.find(m=>m.id===id);return m?`<a class="related-museum" href="#museum/${m.id}">${esc(m.name)} ↗</a>`:''}).join('')}`:''}<p class="tiny-note">名录资料核对：${esc(GUANWU_WORLD_HERITAGE.updated)}。不提供实时票价、余票或开放保证。非遗名录与世界遗产名录是不同体系。</p></section></div>${notePanel('heritage:'+id)}`}
 function journal(){const selected=sites().filter(s=>state.saved.includes('heritage:'+s.id));return selected.length?`<section class="section">${head('收藏的世界遗产','SAVED HERITAGE')}<div class="heritage-grid">${selected.map(card).join('')}</div></section>`:''}
 function teaser(){return `<section class="heritage-home-teaser"><div><div class="eyebrow">CHINA · WORLD HERITAGE</div><h2>一座馆之外，<br>还有一整个世界。</h2><p>42 项文化遗产、4 项文化与自然双遗产，从省份出发，读懂每一处值得留下的风景。</p><a class="solid-btn" href="#heritage">打开世界遗产地图册 ↗</a></div><a href="#heritage/wh-440">${photo(byId('wh-440')?.cover,'loading="lazy"')}<span>沿着文化的线索，走向下一站 ↗</span></a></section>`}
 function mount(route){cancelAnimationFrame(frame);if(map){map.remove();map=null}if(!route.startsWith('heritage/'))return;const s=byId(route.split('/')[1]);if(!s?.location||!window.L)return;frame=requestAnimationFrame(()=>{const el=document.getElementById('heritage-map');if(!el)return;const p=s.location;map=L.map(el,{scrollWheelZoom:false}).setView([p.lat,p.lng],s.components?.length>1?5:11);if(navigator.onLine){const t=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,referrerPolicy:'strict-origin-when-cross-origin',updateWhenIdle:true,keepBuffer:0,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);let failed=false;t.on('tileerror',()=>{if(!failed){failed=true;el.insertAdjacentHTML('afterend','<p class="tiny-note">底图暂未加载，仍可打开名称检索与官方来源。</p>')}})}const popup=document.createElement('div');popup.textContent=s.name+' · UNESCO 参考点，非游客入口';L.marker([p.lat,p.lng]).addTo(map).bindPopup(popup)})}
 document.addEventListener('input',e=>{if(e.target.id==='heritage-search'){query=e.target.value.trim();document.getElementById('heritage-results').innerHTML=results()}});
 document.addEventListener('change',e=>{if(e.target.id==='heritage-province'){province=e.target.value;document.getElementById('heritage-results').innerHTML=results()}if(e.target.id==='heritage-category'){category=e.target.value;document.getElementById('heritage-results').innerHTML=results()}});
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.heritageListen){const s=byId(b.dataset.heritageListen);GuanwuVoices.stopPreview();player.select({id:'heritage:'+s.id,title:s.name,href:'#heritage/'+s.id},[{title:'遗产简介 · '+s.name,text:s.narrationText,src:'assets/audio/heritage/'+s.id+'.mp3'}],0)}if(b?.dataset.heritageAsk){const s=byId(b.dataset.heritageAsk);window.dispatchEvent(new CustomEvent('guanwu:ask',{detail:{message:'请先查阅'+s.name+'的正式世界遗产资料，说明为什么值得看，给我三个观察重点，并提醒名录范围与实际参观入口有什么不同。'}}))}});
 return {sites,byId,provinces,page,detail,journal,teaser,mount};
})();
